// texts returns the messages without arguments in lang, nil for a
// language the catalog lacks.
func texts(lang string) *i18n.Texts {
	switch lang {
	case "en":
		return textsEn
	case "de":
		return textsDe
	case "es":
		return textsEs
	case "fr":
		return textsFr
	case "it":
		return textsIt
	case "ja":
		return textsJa
	case "ko":
		return textsKo
	case "pt-BR":
		return textsPtBR
	case "ru":
		return textsRu
	case "zh-Hans":
		return textsZhHans
	case "zh-Hant":
		return textsZhHant
	}
	return nil
}

