// text says the message without arguments at i in the language of msgs,
// else of the languages it falls back to, else of the source.
func (msgs Messages) text(i int) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, textsEn.At(i))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if t := suppliedTexts[lang]; t != nil && t[i] != "" {
			return t[i]
		}
		if lang == "" {
			return textsEn.At(i)
		}
		if t := texts(lang); t != nil {
			if s := t.At(i); s != "" {
				return s
			}
		}
	}
}

// Supply adds the messages t has in lang to the catalog, over its own.
// nsgo writes the calls, in the package that supplies them, which runs
// them as it initializes.
func Supply(lang string, t Translation) {
	if len(t.Texts) > 0 {
		st := suppliedTexts[lang]
		if st == nil {
			st = new([numTexts]string)
			suppliedTexts[lang] = st
		}
		for i, key := range keyOfText {
			if s, ok := t.Texts[key]; ok {
				st[i] = s
			}
		}
	}
	s := supplied[lang]
	if t.WorksTabCount != nil {
		s.WorksTabCount = t.WorksTabCount
	}
	if t.EyebrowTodayGroup != nil {
		s.EyebrowTodayGroup = t.EyebrowTodayGroup
	}
	if t.EyebrowPreviewGroup != nil {
		s.EyebrowPreviewGroup = t.EyebrowPreviewGroup
	}
	if t.EyebrowLookbookNo != nil {
		s.EyebrowLookbookNo = t.EyebrowLookbookNo
	}
	if t.EyebrowNewLook != nil {
		s.EyebrowNewLook = t.EyebrowNewLook
	}
	if t.StepTab != nil {
		s.StepTab = t.StepTab
	}
	if t.SelectedItem != nil {
		s.SelectedItem = t.SelectedItem
	}
	if t.ViaService != nil {
		s.ViaService = t.ViaService
	}
	if t.ZoomPercent != nil {
		s.ZoomPercent = t.ZoomPercent
	}
	if t.AllCount != nil {
		s.AllCount = t.AllCount
	}
	if t.FavoritesCount != nil {
		s.FavoritesCount = t.FavoritesCount
	}
	if t.UploadsCount != nil {
		s.UploadsCount = t.UploadsCount
	}
	if t.GalleryCount != nil {
		s.GalleryCount = t.GalleryCount
	}
	if t.UploadName != nil {
		s.UploadName = t.UploadName
	}
	if t.TapToTry != nil {
		s.TapToTry = t.TapToTry
	}
	if t.SwapTo != nil {
		s.SwapTo = t.SwapTo
	}
	if t.SavedToWorks != nil {
		s.SavedToWorks = t.SavedToWorks
	}
	if t.OpenWork != nil {
		s.OpenWork = t.OpenWork
	}
	if t.ModelsFailed != nil {
		s.ModelsFailed = t.ModelsFailed
	}
	if t.ConnectionFailed != nil {
		s.ConnectionFailed = t.ConnectionFailed
	}
	if t.StatusConnected != nil {
		s.StatusConnected = t.StatusConnected
	}
	if t.StatusUntested != nil {
		s.StatusUntested = t.StatusUntested
	}
	if t.StatusTesting != nil {
		s.StatusTesting = t.StatusTesting
	}
	if t.StatusFailed != nil {
		s.StatusFailed = t.StatusFailed
	}
	supplied[lang] = s
	Catalog.Add(lang)
}

// arg is what an argument wrote, marked in the source's message for a
// pseudo locale.
func (msgs Messages) arg(s string) string {
	if msgs.mark {
		return i18n.Arg(s)
	}
	return s
}

